basics.bnf_syntax:
component_implementation ::=
  component_category component_type_name . implementation_name
  [ subcomponents
    { subcomponent_declaration }+
  ]
  [ connections
    { connection_declaration }+
  ]
  [ calls
    { subprogram_call_sequence }*
  ]
  [ flows
    { flow_implementation }+
  ]
  [ modes
    { mode_implementation }+
    [ mode transitions
        { mode_transition }+
    ]
  ]
  [ properties
    { property_association }*
  ]
  end component_type_name . implementation_name ;

