  m1 : initial mode;
  m2 : initial mode;

basics.bnf_syntax:
modes_subclause ::=
    modes ( { mode | mode_transition }
    + | none_statement )

valid_examples.code:
modes
  Normal : initial mode;
  Degraded : mode;
  Normal -> Degraded (fault_event);

modes
  On : initial mode;
  Off : mode;
  On -> Off (shutdown);
  Off -> On (startup);

annex Behavior_Specification (**
